pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address candidate) internal {
        vm.assume(candidate != address(0));
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool firstReverted;
        try c.setOwner(candidate) returns (bool ok) { firstReverted = false; } catch { firstReverted = true; }
        address ownerAfterFirst;
        try c.owner() returns (address __r) { ownerAfterFirst = __r; } catch { return; }
        bool secondReverted;
        try c.setOwner(candidate) returns (bool ok2) { secondReverted = false; } catch { secondReverted = true; }
        address ownerAfterSecond;
        try c.owner() returns (address __r) { ownerAfterSecond = __r; } catch { return; }
        assertTrue(((ownerBefore == address(this) && firstReverted == false && ownerAfterFirst == candidate) ||
             (ownerBefore != address(this) && firstReverted == true && ownerAfterFirst == ownerBefore))
            &&
            // Second call correctness (caller is still this contract, but ownership before second call is ownerAfterFirst)
            ((ownerAfterFirst == address(this) && secondReverted == false && ownerAfterSecond == candidate) ||
             (ownerAfterFirst != address(this) && secondReverted == true && ownerAfterSecond == ownerAfterFirst)));
    }

    function testFuzz_run(address candidate) public {
        vm.assume(candidate.code.length == 0 && uint160(candidate) > 0xffff && candidate != address(this) && candidate != address(c) && candidate != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && candidate != 0x000000000000000000636F6e736F6c652e6c6f67 && candidate != 0x4e59b44847b379578588920cA78FbF26c0B4956C && candidate != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(candidate);
    }

    receive() external payable { }
}
